<?php
require_once 'config/database.php';require_once 'includes/functions.php';require_login();
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM suppliers WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('Supplier deleted.');header('Location: suppliers.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');if(!$name){flash('Supplier name is required.','danger');}else{if($id){$s=$conn->prepare('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?');$s->bind_param('ssssi',$name,$phone,$email,$address,$id);}else{$s=$conn->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$s->bind_param('ssss',$name,$phone,$email,$address);}$s->execute();flash('Supplier saved successfully.');}header('Location: suppliers.php');exit;}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM suppliers WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}$rows=$conn->query('SELECT s.*,COUNT(p.id) product_count FROM suppliers s LEFT JOIN products p ON p.supplier_id=s.id GROUP BY s.id ORDER BY s.name');$pageTitle='Suppliers';$active='suppliers';require 'includes/header.php';?>
<div class="row"><div class="col-md-4"><div class="card card-primary"><div class="card-header"><h3 class="card-title"><?=$edit?'Edit':'Add'?> Supplier</h3></div><form method="post"><div class="card-body"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-group"><label>Supplier Name *</label><input class="form-control" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="form-group"><label>Phone</label><input class="form-control" name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="form-group"><label>Email</label><input type="email" class="form-control" name="email" value="<?=e($edit['email']??'')?>"></div><div class="form-group"><label>Address</label><textarea class="form-control" name="address"><?=e($edit['address']??'')?></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Save Supplier</button> <a href="suppliers.php" class="btn btn-default">Clear</a></div></form></div></div><div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Supplier List</h3></div><div class="card-body table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td><?=$r['product_count']?></td><td><a class="btn btn-xs btn-info" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-xs btn-danger" onclick="return confirm('Delete supplier?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php require 'includes/footer.php';?>
